/**
 * Shared Azure Key Vault helpers, used by bruno-electron and bruno-cli.
 *
 * The Azure SDKs are `require`d lazily so importing this module never fails when those optional
 * dependencies aren't installed. Proxy/TLS is environment-specific, so callers pass a
 * `resolveAgents(url)` that returns `{ httpAgent, httpsAgent }` for a request URL. The Azure CLI
 * credential path (`useCLI`) relies on the caller having set up the `az` CLI environment.
 */

import fs from 'node:fs';
import path from 'node:path';
import { get, isUndefined, isNull } from 'lodash';
import { getCACertificates } from '../../../utils/ca-cert';
import { buildResolveAgents } from '../resolve-agents';
import type { ResolveAgents, SecretManagerNetworkConfig } from '../resolve-agents';

export interface AzureKeyVaultConfig {
  tenantId?: string;
  clientId?: string;
  clientSecret?: string;
}

export interface AzureSecretResult {
  vaultName: string;
  data?: Record<string, any>;
  error?: string;
}

// Azure Key Vault names: 3-24 chars, alphanumeric + hyphens, start with a letter, end with a
// letter or digit, no consecutive hyphens.
// https://learn.microsoft.com/en-us/azure/azure-resource-manager/management/resource-name-rules#microsoftkeyvault
// Validated before the name is interpolated into the vault URL: without this, a name containing
// `#`, `?`, `/`, or `:` (e.g. from a shared collection) terminates the intended `.vault.azure.net`
// host and reroutes the Azure AD bearer token to an attacker-controlled host.
const AZURE_VAULT_NAME_REGEX = /^(?=.{3,24}$)[a-zA-Z](?:-?[a-zA-Z0-9])+$/;

// Build an Azure SDK httpClient that routes requests through the supplied proxy/TLS agents,
// resolved per request URL (so proxy-bypass rules are evaluated against each target).
export const createAzureProxyHttpClient = (resolveAgents: ResolveAgents) => {
  const { createDefaultHttpClient } = require('@azure/core-rest-pipeline');
  const defaultClient = createDefaultHttpClient();
  return {
    sendRequest: async (request: any) => {
      const { httpAgent, httpsAgent } = await resolveAgents(request.url);
      const parsedUrl = new URL(request.url);
      if (parsedUrl.protocol === 'https:') {
        if (httpsAgent) request.agent = httpsAgent;
      } else if (httpAgent) {
        request.agent = httpAgent;
      }
      return defaultClient.sendRequest(request);
    }
  };
};

// Fetch all enabled secrets from each Azure Key Vault. Uses client-secret auth by default, or
// the Azure CLI credential when `useCLI` is set (the caller is responsible for any CLI env setup).
export const fetchAzureKeyVaultSecrets = async ({
  azureConfig,
  vaultNames,
  networkConfig,
  useCLI = false
}: {
  azureConfig?: AzureKeyVaultConfig;
  vaultNames: string[];
  networkConfig?: SecretManagerNetworkConfig;
  useCLI?: boolean;
}): Promise<AzureSecretResult[]> => {
  const { ClientSecretCredential, AzureCliCredential } = require('@azure/identity');
  const { SecretClient } = require('@azure/keyvault-secrets');

  const httpClient = createAzureProxyHttpClient(buildResolveAgents(networkConfig));
  const credential = useCLI
    ? new AzureCliCredential()
    : new ClientSecretCredential(azureConfig?.tenantId, azureConfig?.clientId, azureConfig?.clientSecret, { httpClient });

  return Promise.all(
    (vaultNames || []).map(async (vaultName): Promise<AzureSecretResult> => {
      if (!AZURE_VAULT_NAME_REGEX.test(vaultName)) {
        return { vaultName, error: 'Invalid Azure Key Vault name' };
      }
      try {
        const keyVaultUrl = `https://${vaultName}.vault.azure.net`;
        const secretClient = new SecretClient(keyVaultUrl, credential, { httpClient });
        const data: Record<string, any> = {};
        for await (const props of secretClient.listPropertiesOfSecrets()) {
          if (!props.enabled) continue;
          try {
            const { value } = await secretClient.getSecret(props.name);
            data[props.name] = value;
          } catch (_) {
            // skip secrets that can't be read; continue with the rest
          }
        }
        return { vaultName, data };
      } catch (error: any) {
        return { vaultName, error: error?.message || 'Unknown error' };
      }
    })
  );
};

export const azureWhoami = async ({
  config,
  networkConfig
}: {
  config: { azureConfig: AzureKeyVaultConfig };
  networkConfig?: SecretManagerNetworkConfig;
}): Promise<{ status: string; message: string } | undefined> => {
  const { ClientSecretCredential } = require('@azure/identity');
  try {
    const httpClient = createAzureProxyHttpClient(buildResolveAgents(networkConfig));
    const credential = new ClientSecretCredential(
      config.azureConfig.tenantId,
      config.azureConfig.clientId,
      config.azureConfig.clientSecret,
      { httpClient }
    );
    const token = await credential.getToken('https://management.azure.com/.default');
    if (token?.token) {
      return { status: 'success', message: 'Azure credentials are valid' };
    }
    throw new Error('Failed to validate Azure credentials');
  } catch (error: any) {
    throw new Error(error.message || 'Failed to validate Azure credentials');
  }
};

const snapshotEnvVar = (name: string) => {
  const original = process.env[name];
  return () => {
    if (original === undefined) {
      delete process.env[name];
    } else {
      process.env[name] = original;
    }
  };
};

export interface SetupAzureCliEnvParams {
  // TLS/CA settings (the `getHttpHttpsAgents` options subset relevant to the az CLI subprocess).
  options: {
    shouldVerifyTls?: boolean;
    shouldUseCustomCaCertificate?: boolean;
    customCaCertificateFilePath?: string;
    shouldKeepDefaultCaCertificates?: boolean;
  };
  // App-level (global) proxy config, used to derive HTTPS_PROXY/HTTP_PROXY/NO_PROXY.
  appLevelProxyConfig?: any;
  // Directory under which a private per-run subdir is created to hold the merged CA bundle
  // (e.g. <userData> for electron, the collection root for the CLI). Must be user-writable.
  caBundleDir: string;
}

/**
 * Set up environment variables so the Python-based `az` CLI subprocess uses the same CA
 * certificates and proxy configuration that the host app has configured.
 *
 * CA certs:  Writes the merged PEM bundle into a private per-run subdir of `caBundleDir` and sets
 *            REQUESTS_CA_BUNDLE.
 * Proxy:     When a custom proxy is configured (mode "on"), sets HTTPS_PROXY / HTTP_PROXY /
 *            NO_PROXY so the `az` CLI routes through it. In "system" mode the env vars are
 *            already present.
 *
 * Returns a cleanup function that restores all modified env vars to their original values and
 * deletes the per-run CA bundle dir it created. Callers must invoke it in a finally block.
 */
export const setupAzureCliEnv = ({ options, appLevelProxyConfig, caBundleDir }: SetupAzureCliEnvParams) => {
  const restorers: Array<() => void> = [];

  // Always pass custom CA certs to the az CLI subprocess via REQUESTS_CA_BUNDLE when available.
  // MSAL (used by az CLI for token acquisition) ignores AZURE_CLI_DISABLE_CONNECTION_VERIFICATION
  // by design — REQUESTS_CA_BUNDLE is the only supported way to trust intercepting proxy CAs.
  // See: https://github.com/Azure/azure-cli/issues/32207
  const caCertFilePath = options.shouldUseCustomCaCertificate ? options.customCaCertificateFilePath : undefined;
  const caCertificatesData = getCACertificates({
    caCertFilePath,
    shouldKeepDefaultCerts: options.shouldKeepDefaultCaCertificates
  });

  if (caCertificatesData.caCertificates && caCertificatesData.caCertificates.length > 0) {
    // Write the bundle into a private per-run subdir (mkdtemp → unguessable name, owned by the
    // current user) so concurrent runs sharing caBundleDir don't clash and nothing predictable
    // lingers. The whole subdir is removed when the caller restores the env — it's only needed for
    // the az subprocess between setup and restore.
    const caBundleSubDir = fs.mkdtempSync(path.join(caBundleDir, '.bruno-az-'));
    const removeSubDir = () => {
      try {
        fs.rmSync(caBundleSubDir, { recursive: true, force: true });
      } catch (_) {
        // best-effort cleanup
      }
    };
    const caBundlePath = path.join(caBundleSubDir, 'ca-bundle.pem');
    try {
      fs.writeFileSync(caBundlePath, caCertificatesData.caCertificates, { mode: 0o600 });
    } catch (error) {
      // The dir was created but the bundle wasn't written — clean it up rather than leaking it,
      // since no restorer has been registered yet.
      removeSubDir();
      throw error;
    }
    restorers.push(snapshotEnvVar('REQUESTS_CA_BUNDLE'));
    process.env.REQUESTS_CA_BUNDLE = caBundlePath;
    restorers.push(removeSubDir);
  }

  if (!options.shouldVerifyTls) {
    restorers.push(snapshotEnvVar('AZURE_CLI_DISABLE_CONNECTION_VERIFICATION'));
    process.env.AZURE_CLI_DISABLE_CONNECTION_VERIFICATION = '1';
  }

  const globalProxy = appLevelProxyConfig;
  const globalDisabled = get(globalProxy, 'disabled', false);
  const globalInherit = get(globalProxy, 'inherit', false);

  // proxy mode "on" (custom proxy): set HTTPS_PROXY/HTTP_PROXY/NO_PROXY for the az CLI subprocess
  // proxy mode "system" (inherit from OS): env vars are already present, nothing to do
  // proxy mode "off" (disabled): no proxy needed
  if (!globalDisabled && !globalInherit) {
    const proxyConfig = get(globalProxy, 'config', globalProxy);
    const proxyProtocol = get(proxyConfig, 'protocol', 'http');
    const proxyHostname = get(proxyConfig, 'hostname', '');
    const proxyPort = get(proxyConfig, 'port');
    const proxyAuthEnabled = !get(proxyConfig, 'auth.disabled', false);
    const bypassProxy = get(proxyConfig, 'bypassProxy', '');

    if (proxyHostname) {
      const uriPort = isUndefined(proxyPort) || isNull(proxyPort) ? '' : `:${proxyPort}`;
      let proxyUri;
      if (proxyAuthEnabled) {
        const username = encodeURIComponent(get(proxyConfig, 'auth.username', ''));
        const password = encodeURIComponent(get(proxyConfig, 'auth.password', ''));
        proxyUri = `${proxyProtocol}://${username}:${password}@${proxyHostname}${uriPort}`;
      } else {
        proxyUri = `${proxyProtocol}://${proxyHostname}${uriPort}`;
      }

      restorers.push(snapshotEnvVar('HTTPS_PROXY'));
      restorers.push(snapshotEnvVar('HTTP_PROXY'));
      process.env.HTTPS_PROXY = proxyUri;
      process.env.HTTP_PROXY = proxyUri;

      if (bypassProxy) {
        restorers.push(snapshotEnvVar('NO_PROXY'));
        process.env.NO_PROXY = bypassProxy;
      }
    }
  }

  return () => restorers.forEach((restore) => restore());
};

// Validate Azure credentials through the `az` CLI credential. The CLI subprocess is pointed at
// the host app's CA bundle/proxy first (via setupAzureCliEnv) and the env is restored afterwards.
export const azureWhoamiWithCLI = async ({
  options,
  appLevelProxyConfig,
  caBundleDir
}: SetupAzureCliEnvParams): Promise<{ status: string; message: string }> => {
  const { AzureCliCredential } = require('@azure/identity');
  const restoreEnv = setupAzureCliEnv({ options, appLevelProxyConfig, caBundleDir });
  try {
    const credential = new AzureCliCredential();
    const token = await credential.getToken('https://management.azure.com/.default');
    if (token?.token) {
      return { status: 'success', message: 'Azure CLI authentication successful' };
    }
    throw new Error('No access token received from Azure CLI.');
  } catch (error: any) {
    console.error('Azure CLI token retrieval error:', error);
    throw new Error(error.message || 'Failed to authenticate with Azure CLI');
  } finally {
    restoreEnv();
  }
};
